}
const eventAttrs = [
  'onclick', 'onmousedown', 'onmouseup', 'ondblclick',
  'onmouseover', 'onmouseout', 'onfocus', 'onblur',
  'onkeydown', 'onkeyup', 'onchange', 'onsubmit'
